// SPDX-License-Identifier: GPL-2.0
/*
 * Samsung S5KGN1 (ISOCELL GN1) image sensor driver.
 *
 * Register tables are the Pixel 6 stock camera HAL's (liblyric_hwl.so,
 * sensor "nagual"), replayed verbatim; see RE/gn1/README.md in the port tree.
 * Structure follows s5kjn1.c.
 */

#include <linux/clk.h>
#include <linux/delay.h>
#include <linux/gpio/consumer.h>
#include <linux/i2c.h>
#include <linux/module.h>
#include <linux/pm_runtime.h>
#include <linux/regulator/consumer.h>
#include <linux/units.h>
#include <media/v4l2-cci.h>
#include <media/v4l2-ctrls.h>
#include <media/v4l2-device.h>
#include <media/v4l2-fwnode.h>

/*
 * PLL registers in the HAL init table: pre_pll_clk_div (0x0304) = 4,
 * pll_multiplier (0x0306) = 266, op_sys_clk_div (0x030a) = 2 ->
 * 24 MHz / 4 * 266 / 2 = 798 MHz D-PHY link frequency (1596 Mbps per lane).
 * The HAL runs the tables from a 24.576 MHz oscillator (0x0136 = 0x1894);
 * this driver runs them from 24.000 MHz and writes 0x0136 accordingly.
 */
#define S5KGN1_LINK_FREQ		(798ULL * HZ_PER_MHZ)
#define S5KGN1_MCLK_FREQ_24MHZ		(24 * HZ_PER_MHZ)
#define S5KGN1_DATA_LANES		3	/* C-PHY trios (0x0114 = 0x02 in the HAL tables) */

#define S5KGN1_REG_CHIP_ID		CCI_REG16(0x0000)

#define S5KGN1_REG_CTRL_MODE		CCI_REG8(0x0100)
#define S5KGN1_MODE_STREAMING		BIT(0)

#define S5KGN1_REG_ORIENTATION		CCI_REG8(0x0101)
#define S5KGN1_VFLIP			BIT(1)
#define S5KGN1_HFLIP			BIT(0)

#define S5KGN1_REG_EXTCLK_MHZ		CCI_REG16(0x0136)	/* 8.8 fixed point */
#define S5KGN1_EXTCLK_24MHZ		0x1800

#define S5KGN1_REG_EXPOSURE		CCI_REG16(0x0202)
#define S5KGN1_EXPOSURE_MIN		8
#define S5KGN1_EXPOSURE_STEP		1

#define S5KGN1_REG_AGAIN		CCI_REG16(0x0204)
#define S5KGN1_AGAIN_MIN		1
#define S5KGN1_AGAIN_MAX		16
#define S5KGN1_AGAIN_STEP		1
#define S5KGN1_AGAIN_DEFAULT		1
#define S5KGN1_AGAIN_SHIFT		5

#define S5KGN1_REG_VTS			CCI_REG16(0x0340)
#define S5KGN1_VTS_MAX			0xffff

#define S5KGN1_REG_TEST_PATTERN		CCI_REG16(0x0600)

#define to_s5kgn1(_sd)			container_of(_sd, struct s5kgn1, sd)

static const s64 s5kgn1_link_freq_menu[] = {
	S5KGN1_LINK_FREQ,
};

/* Index = (vflip << 1) | hflip. The order at index 0 is not yet verified. */
static const u32 s5kgn1_mbus_formats[] = {
	MEDIA_BUS_FMT_SRGGB10_1X10,	MEDIA_BUS_FMT_SGRBG10_1X10,
	MEDIA_BUS_FMT_SGBRG10_1X10,	MEDIA_BUS_FMT_SBGGR10_1X10,
};

struct s5kgn1_reg_list {
	const struct cci_reg_sequence *regs;
	unsigned int num_regs;
};

struct s5kgn1_mode {
	u32 width;
	u32 height;
	u32 hts;			/* line_length_pck (0x0342) in the table */
	u32 vts;			/* frame_length_lines (0x0340) in the table */
	u32 exposure;			/* coarse_integration_time (0x0202) in the table */
	u32 exposure_margin;
	struct v4l2_rect crop;		/* pixel-array crop (0x0344..0x034a) in the table */

	const struct s5kgn1_reg_list reg_list;
};

static const char * const s5kgn1_test_pattern_menu[] = {
	"Disabled",
	"Solid color",
	"Color bars",
	"Fade to grey color bars",
	"PN9",
};

struct s5kgn1 {
	struct device *dev;
	struct regmap *regmap;
	struct clk *mclk;
	struct gpio_desc *reset_gpio;
	struct gpio_desc *enable_gpio[3];	/* camera PMIC GPIO enables, see power_on */
	struct regulator *avdd;
	struct regulator *dvdd;
	struct regulator *dovdd;

	struct v4l2_subdev sd;
	struct media_pad pad;

	struct v4l2_ctrl_handler ctrl_handler;
	struct v4l2_ctrl *link_freq;
	struct v4l2_ctrl *pixel_rate;
	struct v4l2_ctrl *hblank;
	struct v4l2_ctrl *vblank;
	struct v4l2_ctrl *exposure;
	struct v4l2_ctrl *vflip;
	struct v4l2_ctrl *hflip;

	const struct s5kgn1_mode *mode;
};

